   537	/**
   538	 * Conservative source classifier used by the contract smoke. Any production
   539	 * file that imports a provider adapter, is itself an adapter, or combines a
   540	 * child-process API with provider vocabulary must have an explicit inventory
   541	 * row. False positives are classified, never silently excluded, so adding a
   542	 * new direct provider spawn in a new file makes the contract fail closed.
   543	 */
   544	export function isProviderExecutionSurfaceCandidate(relativePath: string, source: string): boolean {
   545	  if (!relativePath.endsWith('.ts')) return false;
   546	  if (/(?:^|\/)(?:tasks|tests|generated)(?:\/|$)/.test(relativePath)) return false;
   547	  if (relativePath === 'core/provider-process-registry.ts') return false;
   548	  if (/^providers\/(?:codex-cli|claude-cli|gemini-cli)\.ts$/.test(relativePath)) return true;
   549	  if (/providers\/(?:codex-cli|claude-cli|gemini-cli)\.js/.test(source)) return true;
   550	  if (/\brunHostRun\s*\(/.test(source)) return true;
   551	  // B-137a: strip documentation filename references before the provider-word
   552	  // scan. The words are matched case-insensitively, so a prose citation of
   553	  // "CLAUDE.md" (the project convention doc, referenced by many core modules)
   554	  // read as a provider reference: any file that both used child_process for git
   555	  // and cited that doc became an "unclassified provider execution surface".
   556	  // scope-contract.ts tripped exactly this way on a comment citing the handler
   557	  // convention -- a docs citation, not a provider workload. Several already
   558	  // inventoried files (audit-scan, audit-trigger, rollout-check,
   559	  // runtime-environment-checks) match for the same non-reason. Stripping only
   560	  // "<provider>.md" filenames keeps every real provider reference intact,
   561	  // including CLAUDE_CLI, claudeCli, 'claude' and providers/claude-cli.js.
   562	  const withoutDocReferences = source.replace(/\b(?:codex|claude|agy|gemini|antigravity)\.md\b/gi, '');
   563	  // Demand a real child-process launch whose *argument* carries provider
   564	  // identity. A module can legitimately run Git (or its own lifecycle hooks)
   565	  // while describing Codex or Claude elsewhere in comments and diagnostics;
   566	  // treating that co-occurrence as a provider launch made the inventory claim
   567	  // false positives. Preserve identifier forms such as `claudeCli` and command
   568	  // variables such as `const command = 'codex'; spawn(command)` by resolving
   569	  // the first argument or its local initializer, rather than scanning the
   570	  // entire file for provider vocabulary.
   571	  const importsChildProcess = /(?:\bfrom\s*|\brequire\s*\(\s*|\bimport\s*)(['"])(?:node:)?child_process\1/.test(source);
   572	  if (!importsChildProcess) return false;
   573	  const launchApi = '(?:spawn|spawnSync|execFile|execFileSync|exec)';
   574	  const aliasNames = new Set<string>();
   575	  const aliasPatterns = [
   576	    new RegExp(`\\b${launchApi}\\s+as\\s+([A-Za-z_$][\\w$]*)`, 'g'),
   577	    new RegExp(`\\b${launchApi}\\s*:\\s*([A-Za-z_$][\\w$]*)`, 'g'),
   578	    new RegExp(`\\b(?:const|let|var)\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*[A-Za-z_$][\\w$]*\\s*\\.\\s*${launchApi}\\b`, 'g'),
   579	  ];
   580	  for (const pattern of aliasPatterns) {
   581	    for (const match of withoutDocReferences.matchAll(pattern)) aliasNames.add(match[1]!);
   582	  }
   583	  // Comments are not launch sites. Strip them only after collecting import and
   584	  // alias bindings, because an import / alias itself is source syntax rather
   585	  // than a comment-derived provider word.
   586	  const launchSource = withoutDocReferences.replace(/\/\*[\s\S]*?\*\/|\/\/[^\r\n]*/g, '');
   587	  const aliasApi = [...aliasNames].map(name => name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|');
   588	  const launchCallee = aliasApi.length > 0
   589	    ? `(?:${launchApi}|[A-Za-z_$][\\w$]*\\s*\\.\\s*${launchApi}|${aliasApi})`
   590	    : `(?:${launchApi}|[A-Za-z_$][\\w$]*\\s*\\.\\s*${launchApi})`;
   591	  const providerToken = /(?:codex|claude|agy|gemini|antigravity)/i;
   592	  const launchCall = new RegExp(`\\b${launchCallee}\\s*\\(\\s*([^,\\r\\n)]*)`, 'g');
   593	  for (const match of launchSource.matchAll(launchCall)) {
   594	    const firstArgument = match[1]!.trim();
   595	    if (providerToken.test(firstArgument)) return true;
   596	    const identifier = firstArgument.match(/^([A-Za-z_$][\w$]*)$/)?.[1];
   597	    if (!identifier) continue;
   598	    const escapedIdentifier = identifier.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
   599	    if (new RegExp(`\\b(?:const|let|var)\\s+${escapedIdentifier}\\s*=\\s*[^;\\r\\n]*?(?:codex|claude|agy|gemini|antigravity)`, 'i').test(launchSource)) return true;
   600	  }
   601	  return false;
   602	}
