    95	  ]) assert.ok(inventory.has(path), `provider execution surface must be classified: ${path}`);
    96	  assert.equal(inventory.get('core/host-run.ts')?.status, 'admission_only',
    97	    'runHostRun acquires its own provider-admission slot instead of delegating admission to its caller');
