   101	  assert.equal(PROVIDER_EXECUTION_SURFACES.some(entry => entry.status === 'legacy_unmanaged'), false,
   102	    'no production provider workload remains silently unmanaged');
   103	
   104	  const candidates = productionSources(sourceRoot)
   105	    .filter(row => isProviderExecutionSurfaceCandidate(row.path, row.source))
   106	    .map(row => row.path)
   107	    .sort();
   108	  const missingInventory = candidates.filter(path => !inventory.has(path));
   109	  assert.deepEqual(missingInventory, [],
   110	    `every discovered provider execution/probe surface must be classified: ${missingInventory.join(', ')}`);
   111	  for (const path of ['core/new-direct-provider.ts', 'cli/new-direct-provider.ts', 'verifier/new-direct-provider.ts', 'new-direct-provider.ts']) {
   112	    assert.equal(
   113	      isProviderExecutionSurfaceCandidate(path, "import { spawn } from 'node:child_process'; spawn('codex', ['exec']);"),
   114	      true,
